using System.Security.Cryptography; using Astraea.Application; using Astraea.Application.Abstractions; using Astraea.Domain; using Microsoft.EntityFrameworkCore;
namespace Astraea.Infrastructure;
public sealed class AuthService(AstraeaDbContext db,IUnitOfWork uow,ITokenFactory tokens):IAuthService { public async Task<AuthResponseDto> RegisterAsync(RegisterUserRequest r,CancellationToken ct){var email=r.Email.Trim().ToLowerInvariant();if(await db.Users.AnyAsync(x=>x.Email==email,ct))throw new InvalidOperationException("An account already uses this email.");var u=new User{Email=email,FullName=r.FullName.Trim(),Role=r.Role,PasswordHash=Hash(r.Password)};db.Users.Add(u);if(r.Role==UserRole.Mentor)foreach(var invite in await db.MentorLearners.Where(x=>x.MentorEmail==email&&x.Status==MentorLearnerStatus.Pending).ToListAsync(ct))invite.MentorUserId=u.Id;await uow.SaveChangesAsync(ct);return new(tokens.Create(u),u.Id,u.FullName,u.Role.ToString());} public async Task<AuthResponseDto> LoginAsync(LoginRequest r,CancellationToken ct){var u=await db.Users.SingleOrDefaultAsync(x=>x.Email==r.Email.Trim().ToLowerInvariant(),ct)??throw new UnauthorizedAccessException("Invalid email or password.");if(!Verify(r.Password,u.PasswordHash))throw new UnauthorizedAccessException("Invalid email or password.");return new(tokens.Create(u),u.Id,u.FullName,u.Role.ToString());} public async Task ChangePasswordAsync(Guid userId,ChangePasswordRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.NewPassword)||r.NewPassword.Length<8)throw new InvalidOperationException("Your new password must be at least eight characters.");var user=await db.Users.SingleOrDefaultAsync(x=>x.Id==userId,ct)??throw new UnauthorizedAccessException();if(!Verify(r.CurrentPassword,user.PasswordHash))throw new InvalidOperationException("Your current password is incorrect.");user.PasswordHash=Hash(r.NewPassword);await uow.SaveChangesAsync(ct);} public async Task ResetForgottenPasswordAsync(ForgotPasswordResetRequest r,CancellationToken ct){var email=r.Email.Trim().ToLowerInvariant();if(string.IsNullOrWhiteSpace(email))throw new InvalidOperationException("Enter the account email first.");if(string.IsNullOrWhiteSpace(r.NewPassword)||r.NewPassword.Length<8)throw new InvalidOperationException("Your new password must be at least eight characters.");var user=await db.Users.SingleOrDefaultAsync(x=>x.Email==email,ct)??throw new InvalidOperationException("No Astraea user exists with that email.");user.PasswordHash=Hash(r.NewPassword);await uow.SaveChangesAsync(ct);} static string Hash(string p){var salt=RandomNumberGenerator.GetBytes(16);var key=Rfc2898DeriveBytes.Pbkdf2(p,salt,210000,HashAlgorithmName.SHA512,32);return Convert.ToBase64String(salt)+":"+Convert.ToBase64String(key);} static bool Verify(string p,string h){var a=h.Split(':');if(a.Length!=2)return false;var v=Rfc2898DeriveBytes.Pbkdf2(p,Convert.FromBase64String(a[0]),210000,HashAlgorithmName.SHA512,32);return CryptographicOperations.FixedTimeEquals(v,Convert.FromBase64String(a[1]));}}
public sealed class SkillService(AstraeaDbContext db,IUnitOfWork uow):ISkillService { public async Task<CelestialNodeDto> CreateSkillAsync(Guid learnerId,CreateSkillRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Title)||string.IsNullOrWhiteSpace(r.ConstellationCategory)||r.InitialRating is <1 or >5)throw new InvalidOperationException("A title, constellation category, and one to five stars are required.");var (ease,days)=r.InitialRating<=2?(1.7,1):r.InitialRating==3?(2.0,3):(2.5,7);var count=await db.Skills.CountAsync(x=>x.LearnerId==learnerId,ct);var angle=count*2.399963229728653;var s=new Skill{LearnerId=learnerId,Title=r.Title.Trim(),ConstellationCategory=r.ConstellationCategory.Trim(),SelfAssessedRating=r.InitialRating,TargetWeeklyHours=r.TargetWeeklyHours,EaseFactor=ease,CurrentIntervalDays=days,LastReviewedUtc=DateTime.UtcNow,NextReviewDueDateUtc=DateTime.UtcNow.AddDays(days),CanvasX=.5+Math.Cos(angle)*.30,CanvasY=.5+Math.Sin(angle)*.30};foreach(var id in r.PrerequisiteSkillIds??[])s.Prerequisites.Add(new(){SkillId=s.Id,PrerequisiteSkillId=id});db.Skills.Add(s);await uow.SaveChangesAsync(ct);return Map(s);} public async Task<IReadOnlyCollection<CelestialNodeDto>> GetSkillsAsync(Guid learnerId,CancellationToken ct){var skills=await db.Skills.AsNoTracking().Include(x=>x.Prerequisites).Where(x=>x.LearnerId==learnerId&&!x.IsArchived).OrderBy(x=>x.Title).ToListAsync(ct);return skills.Select(Map).ToArray();} internal static CelestialNodeDto Map(Skill s){var days=(DateTime.UtcNow-s.LastReviewedUtc).TotalDays;var retention=Math.Clamp(100*Math.Exp(-days/Math.Max(s.CurrentIntervalDays,1)),0,100);var risk=retention>=70?RiskStatus.Fresh:retention>=40?RiskStatus.Fading:RiskStatus.AtRisk;return new(s.Id,s.Title,s.ConstellationCategory,s.SelfAssessedRating,s.EaseFactor,s.CurrentIntervalDays,s.CanvasX,s.CanvasY,retention,risk,s.Prerequisites.Select(x=>x.PrerequisiteSkillId).ToArray());}}
